The same test works for exponential, logarithmic and trigonometric curves; only the derivative changes.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw[thick,<->,domain=-1.2:1.2,smooth,variable=\x] plot ({\x},{1-\x*\x});
\draw[dashed] (-0.5,1) -- (0.5,1);
\node[font=\small] at (0,1.9) {Local maximum};
\node[font=\small] at (0,-1.9) {$f'$: $+$ then $-$};
\draw[thick,<->,domain=-1.2:1.2,smooth,variable=\x] plot ({\x+3.6},{\x*\x-1});
\draw[dashed] (3.1,-1) -- (4.1,-1);
\node[font=\small] at (3.6,1.9) {Local minimum};
\node[font=\small] at (3.6,-1.9) {$f'$: $-$ then $+$};
\draw[thick,<->,domain=-1.2:1.2,smooth,variable=\x] plot ({\x+7.2},{0.8*\x*\x*\x});
\draw[dashed] (6.7,0) -- (7.7,0);
\node[font=\small] at (7.2,1.9) {Horizontal inflection};
\node[font=\small] at (7.2,-1.9) {$f'$: $+$ then $+$};
\end{tikzpicture}
[/tikz]
